USE sakila;

-- Challenge
-- 1. List the number of films per category.
SELECT c.name AS category_name, COUNT(fc.film_id) AS number_of_films 
FROM sakila.film_category fc
JOIN sakila.category c
ON fc.category_id=c.category_id
GROUP BY category_name;

-- 2.Retrieve the store ID, city, and country for each store.
SELECT s.store_id, c.city AS city, co.country AS country
FROM sakila.store s
JOIN sakila.address a
ON s.address_id=a.address_id
JOIN sakila.city c
ON a.city_id=c.city_id
JOIN sakila.country co
ON c.country_id=co.country_id;

-- 3. Calculate the total revenue generated by each store in dollars.
SELECT s.store_id, SUM(p.amount) AS 'total_revenue (Dollars)'
FROM sakila.store s
JOIN sakila.staff st
ON s.store_id = st.store_id
JOIN sakila.payment p
ON st.staff_id=p.staff_id
GROUP BY s.store_id;

-- 4. Determine the average running time of films for each category.
SELECT ca.name AS Category_name, ROUND(AVG(length),0) AS 'avg_running_time(mins)'
FROM sakila.film f
JOIN sakila.film_category c
ON f.film_id=c.film_id
JOIN sakila.category ca
ON c.category_id=ca.category_id
GROUP BY ca.name;

-- Bonus (not mandatoy, only optional):
-- 5. Identify the film categories with the longest average running time.
SELECT ca.name AS Category_name, ROUND(AVG(length),0) AS 'avg_running_time(mins)'
FROM sakila.film f
JOIN sakila.film_category c
ON f.film_id=c.film_id
JOIN sakila.category ca
ON c.category_id=ca.category_id
GROUP BY ca.name ORDER BY `avg_running_time(mins)` DESC LIMIT 1;



